let csrf = '', me = null, activeTab = 'overview', selectedCandidate = '', selectedSubject = '', selectedCredentialSubject = '', selectedTrackSubject = '', onboardingData = null;
let gpsTrackMap = null, gpsTrackLayers = null, gpsTrackTile = null, gpsTrackHours = 12;
let candidateCache = [], subjectCache = [], selectedEditCandidate = '', selectedEditSubject = '';
let incidentGroups = [];
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function toast(msg,kind='info'){const t=$('toast');t.textContent=msg;t.classList.toggle('error',kind==='error');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),kind==='error'?7000:2400)}
window.addEventListener('unhandledrejection',event=>{event.preventDefault();const message=event.reason?.message||String(event.reason||'未知错误');toast(`操作失败：${message}`,'error')});
async function api(url,opts={}){opts.headers={...(opts.headers||{})};if(opts.body&&!opts.headers['Content-Type'])opts.headers['Content-Type']='application/json';if(opts.method&&opts.method!=='GET'&&csrf)opts.headers['X-CSRF-Token']=csrf;const r=await fetch(url,opts);let data=null;try{data=await r.json()}catch{}if(!r.ok)throw new Error(data?.detail||`HTTP ${r.status}`);return data}
function badge(v){const map={running:['运行中','ok'],scheduled:['已预约','info'],completed:['完成',''],canceled:['取消',''],available:['可用','ok'],repair:['维修','warn'],disabled:['停用','danger'],open:['待处理','danger'],connected:['已接入','ok'],manual:['人工链路','warn'],offline:['离线导入',''],pi:['PI','info'],ra:['RA',''],active:['启用','ok'],inactive:['禁用','danger'],ok:['完整','ok'],missing:['缺失','danger'],pending:['待完成','warn'],valid:['有效','ok'],insufficient:['样本不足','warn'],gps_insufficient:['覆盖不足','warn'],unreadable:['无法解析','danger']};const x=map[v]||[v||'—',''];return `<span class="badge ${x[1]}">${esc(x[0])}</span>`}
function fmtTime(s){if(!s)return '—';try{return new Date(s).toLocaleString('zh-CN',{hour12:false})}catch{return s}}
function addLocalDays(value,days){const [y,m,d]=value.split('-').map(Number),next=new Date(Date.UTC(y,m-1,d+days));return next.toISOString().slice(0,10)}
function gpsBadge(v){const map={live:['在线','ok'],backfilling:['补传中','info'],stale:['延迟','warn'],offline:['离线','danger'],never:['无数据',''],unknown:['未知','warn']};const x=map[v]||map.unknown;return `<span class="badge ${x[1]}">${x[0]}</span>`}

function showAuth(which){$('setupView').classList.toggle('hidden',which!=='setup');$('loginView').classList.toggle('hidden',which!=='login');$('appView').classList.add('hidden')}
function showTab(name){if(name==='system'&&me?.role!=='pi')return;activeTab=name;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.querySelectorAll('.tabpage').forEach(x=>x.classList.add('hidden'));$('tab-'+name).classList.remove('hidden');loadTab(name)}
async function initialize(){try{const x=await api('/api/v1/web/me');csrf=x.csrf_token;me=x;return enterApp()}catch{}try{const s=await api('/api/v1/web/setup-status');if(!s.initialized){showAuth('setup');if(s.setup_cli_required)$('setupError').textContent='服务器尚未初始化，请在 ECS 上运行 scripts/server_setup.sh。'}else showAuth('login')}catch(e){showAuth('login');$('loginError').textContent=e.message}}
async function firstSetup(){const p=$('setupPassword').value,p2=$('setupPassword2').value;$('setupError').textContent='';if(p!==p2){$('setupError').textContent='两次密码不一致';return}try{const data=await api('/api/v1/web/setup',{method:'POST',body:JSON.stringify({display_name:$('setupDisplay').value,username:$('setupUser').value,password:p})});csrf=data.csrf_token;me=data.user;enterApp()}catch(e){$('setupError').textContent=e.message}}
async function login(){try{const data=await api('/api/v1/web/login',{method:'POST',body:JSON.stringify({username:$('loginUser').value,password:$('loginPassword').value})});csrf=data.csrf_token;me=data.user;enterApp()}catch(e){$('loginError').textContent=e.message}}
async function enterApp(){if(!me?.date_local){try{const x=await api('/api/v1/web/me');csrf=x.csrf_token;me=x}catch{return initialize()}}$('setupView').classList.add('hidden');$('loginView').classList.add('hidden');$('appView').classList.remove('hidden');$('who').textContent=`${me.display_name||me.username} · ${me.role.toUpperCase()}`;$('systemTab').classList.toggle('hidden',me.role!=='pi');if(!$('iDate').value)$('iDate').value=me.date_local;if(activeTab==='system'&&me.role!=='pi')activeTab='overview';await loadTab(activeTab)}
async function logout(){try{await api('/api/v1/web/logout',{method:'POST',body:'{}'})}catch{}location.reload()}
async function loadTab(name){try{if(name==='overview')await renderDashboard();if(name==='subjects')await renderSubjects();if(name==='candidates')await renderCandidates();if(name==='qc')await renderDailyQc();if(name==='devices')await renderDevices();if(name==='incidents')await renderIncidents();if(name==='system')await renderUsers()}catch(e){toast(e.message)}}

async function renderDashboard(){
  const d=await api('/api/v1/web/dashboard');
  const labels=[['候选池','candidates'],['已预约','scheduled'],['运行中','running'],['未归档异常','open_incidents'],['可用设备包','available_packs'],['已有GPS被试','gps_subjects'],['当前任务问卷','questionnaire_today']];
  $('metrics').innerHTML=labels.map(([l,k])=>`<div class="metric"><div class="label">${l}</div><div class="value">${d.metrics[k]??0}</div></div>`).join('');
  $('runningList').innerHTML=d.running.length?d.running.map(x=>`<div class="issue"><div class="issue-title"><strong>${esc(x.participant_id)}</strong>${badge(x.status)}</div><p>${esc(x.pack_id||'未绑定设备')} · GPS ${x.gps_last_received_at_utc?`最近 ${fmtTime(x.gps_last_received_at_utc)}`:'暂无回传'} · 当前任务问卷 ${x.questionnaire_today_completed||0}/2</p></div>`).join(''):'<div class="muted">暂无运行中被试</div>';
  $('attentionList').innerHTML=d.incidents.length?d.incidents.map(x=>`<div class="issue"><div class="issue-title"><strong>${esc(x.participant_id||'—')} · ${esc(x.summary||x.incident_type)}</strong>${incidentBadge(x.status)}</div><p>${esc(x.source)} · ${esc(x.date_local)}</p></div>`).join(''):'<div class="muted">暂无未归档异常</div>';
}

function populateCandidateFilters(){document.querySelectorAll('[data-candidate-filter]').forEach(select=>{const field=select.dataset.candidateFilter,current=select.value,values=[...new Set(candidateCache.map(x=>x[field]).filter(Boolean))].sort();select.innerHTML=`<option value="">${esc(select.dataset.label)}</option>`+values.map(value=>`<option>${esc(value)}</option>`).join('');select.value=values.includes(current)?current:''})}
function renderCandidateRows(){const q=$('candidateSearch').value.trim().toLowerCase(),status=$('candidateStatus').value,filters=[...document.querySelectorAll('[data-candidate-filter]')];const rows=candidateCache.filter(x=>{const text=Object.values(x).join(' ').toLowerCase(),state=!x.in_latest_snapshot?'history':x.linked_participant_id?'linked':'available';return(!q||text.includes(q))&&(status==='all'||status===state)&&filters.every(select=>!select.value||x[select.dataset.candidateFilter]===select.value)});$('candidateCount').textContent=`显示 ${rows.length} / ${candidateCache.length}`;$('candidateRows').innerHTML=rows.map(x=>`<tr><td><div class="candidate-cell"><strong>${esc(x.name||'—')}</strong><span>${esc(x.phone)}</span><span class="muted">${esc(x.wechat)} · ${esc(x.source)}${x.source_seq?` #${esc(x.source_seq)}`:''}</span></div></td><td><div class="candidate-cell"><span>${esc([x.sex,x.age_group,x.education].filter(Boolean).join(' · ')||'—')}</span><span class="muted">${esc([x.beijing_based,x.identity_type,x.health_rating].filter(Boolean).join(' · '))}</span></div></td><td><div class="candidate-cell"><span>${esc(x.work_schedule||'—')}</span><span class="muted">${esc([x.chronotype,x.activity_mode].filter(Boolean).join(' · '))}</span></div></td><td><div class="candidate-cell"><strong>${esc(x.exposure_mechanism||'待派生')}</strong><span class="muted">固定 ${esc(x.fixed_position_ratio||'—')} · 日光 ${esc(x.indoor_daylight||'—')}</span><span class="muted">户外 ${esc(x.outdoor_time||'—')} · 屏幕 ${esc(x.screen_time_ratio||'—')}</span></div></td><td><div class="candidate-cell"><span>${esc(x.work_district||'—')} / ${esc(x.home_district||'—')}</span><span class="muted">${esc([x.commute_mode,x.commute_duration].filter(Boolean).join(' · '))}</span></div></td><td><div class="candidate-cell"><span>${esc(x.willingness||'—')} · ${esc(x.phone_os||'—')}</span><span class="muted">${esc(x.availability||'')}</span><span class="muted">${esc(x.pickup_method||'')}</span></div></td><td>${esc(x.linked_participant_id||'—')}${!x.in_latest_snapshot?'<br><span class="muted">历史</span>':''}</td><td><div class="subject-actions"><button class="btn small" data-edit-candidate="${esc(x.candidate_uid)}">编辑</button>${!x.linked_participant_id&&x.in_latest_snapshot?`<button class="btn small" data-promote="${esc(x.candidate_uid)}">赋 ID</button>`:''}</div></td></tr>`).join('');document.querySelectorAll('[data-promote]').forEach(b=>b.addEventListener('click',()=>openPromote(b.dataset.promote)));document.querySelectorAll('[data-edit-candidate]').forEach(b=>b.addEventListener('click',()=>openCandidateEdit(b.dataset.editCandidate)))}
async function renderCandidates(){candidateCache=await api('/api/v1/web/candidates');populateCandidateFilters();renderCandidateRows()}
function bytesToBase64(buffer){const bytes=new Uint8Array(buffer);let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
async function importS0(){const file=$('s0File').files[0];if(!file){toast('请选择问卷星 CSV/XLSX');return}$('importS0Btn').disabled=true;try{const result=await api('/api/v1/web/candidates/import-s0',{method:'POST',body:JSON.stringify({filename:file.name,content_b64:bytesToBase64(await file.arrayBuffer())})});$('s0Result').textContent=`原始 ${result.total} 行 · 入池 ${result.imported}${result.duplicate?' · 已导入过':''}`;toast(result.duplicate?'该文件已导入过，未重复写入':'S0 候选池导入完成');await renderCandidates()}finally{$('importS0Btn').disabled=false}}
async function addCandidate(){const body={name:$('cName').value,phone:$('cPhone').value,wechat:$('cWechat').value,source:$('cSource').value,sex:$('cSex').value,age_group:$('cAge').value,identity_type:$('cIdentity').value,phone_os:$('cOs').value,notes:$('cNotes').value};if(!body.name&&!body.phone&&!body.wechat){toast('至少填写姓名或一种联系方式');return}await api('/api/v1/web/candidates',{method:'POST',body:JSON.stringify(body)});['cName','cPhone','cWechat','cNotes'].forEach(id=>$(id).value='');toast('已加入候选池');await renderCandidates()}
function selectValue(id,value){const el=$(id);if(value&&![...el.options].some(o=>o.value===value))el.add(new Option(value,value));el.value=value||''}
function openCandidateEdit(uid){const x=candidateCache.find(row=>row.candidate_uid===uid);if(!x)return;selectedEditCandidate=uid;$('eName').value=x.name||'';$('ePhone').value=x.phone||'';$('eWechat').value=x.wechat||'';selectValue('eSource',x.source);selectValue('eSex',x.sex);selectValue('eAge',x.age_group);selectValue('eIdentity',x.identity_type);selectValue('eOs',x.phone_os);$('eWork').value=x.work_district||'';$('eHome').value=x.home_district||'';$('eAvail').value=x.availability||'';$('eNotes').value=x.notes||'';$('candidateEditDialog').showModal()}
async function saveCandidateEdit(){const body={name:$('eName').value,phone:$('ePhone').value,wechat:$('eWechat').value,source:$('eSource').value,sex:$('eSex').value,age_group:$('eAge').value,identity_type:$('eIdentity').value,phone_os:$('eOs').value,work_district:$('eWork').value,home_district:$('eHome').value,availability:$('eAvail').value,notes:$('eNotes').value};await api(`/api/v1/web/candidates/${encodeURIComponent(selectedEditCandidate)}`,{method:'PUT',body:JSON.stringify(body)});$('candidateEditDialog').close();toast('候选信息已更新');await renderCandidates()}
function openPromote(uid){selectedCandidate=uid;const t=me.date_local;$('pStart').value=t;$('pEnd').value=addLocalDays(t,13);$('pRa').value=me.username||'';$('promoteDialog').showModal()}
async function promote(){const body={participant_id:$('pId').value,batch_id:$('pBatch').value,expected_start:$('pStart').value,expected_end:$('pEnd').value,pack_id:$('pPack').value,assigned_ra:$('pRa').value};await api(`/api/v1/web/candidates/${selectedCandidate}/promote`,{method:'POST',body:JSON.stringify(body)});$('promoteDialog').close();toast('已创建预约');await renderCandidates()}

function renderSubjectRows(){const q=$('subjectSearch').value.trim().toLowerCase(),filter=$('subjectStatus').value;const rows=subjectCache.filter(x=>{const text=`${x.participant_id} ${x.name||''}`.toLowerCase();return(!q||text.includes(q))&&(filter==='all'||filter===x.status)});$('subjectCount').textContent=`${rows.length} / ${subjectCache.length}`;$('subjectRows').innerHTML=rows.map(x=>`<tr><td><strong>${esc(x.participant_id)}</strong></td><td>${esc(x.name||'—')}<br><span class="muted">${esc(x.phone||'')}</span></td><td>${badge(x.status)}</td><td>${x.status==='running'&&x.study_day?`Day ${x.study_day}`:'—'}</td><td>${esc(x.start_date||x.expected_start||'—')} → ${esc(x.end_date||x.expected_end||'—')}</td><td>${esc(x.pack_id||'—')}</td><td>${esc(x.assigned_ra||'—')}</td><td><div class="gps-cell">${gpsBadge(x.gps_status)}<span class="muted">${x.gps_last_received_at_utc?fmtTime(x.gps_last_received_at_utc):'暂无回传'}${x.gps_status==='backfilling'&&x.gps_delivery_delay_seconds?` · 记录晚到 ${formatGap(x.gps_delivery_delay_seconds)}`:''}</span></div></td><td>${x.questionnaire_today_completed||0}/2</td><td>${x.lighting_today?.uploaded?`${badge(x.lighting_today.quality)} ${x.lighting_today.valid_pct??''}%`:'未上传'}</td><td>${x.portal_enabled?badge('connected'):'未生成'}</td><td><div class="subject-actions">${x.status==='scheduled'?`<button class="btn small" data-start="${x.participant_id}" data-pack="${esc(x.pack_id)}">启动</button>`:`<button class="btn small" data-onboarding="${x.participant_id}">入组卡</button>`}${x.status==='running'?`<button class="btn small danger" data-complete="${x.participant_id}">完成并回收</button>`:''}<button class="btn small" data-edit-subject="${esc(x.participant_id)}">编辑</button><button class="btn small" data-gps-track="${esc(x.participant_id)}">轨迹</button><button class="btn small" data-credentials="${x.participant_id}">凭据</button></div></td></tr>`).join('');
  document.querySelectorAll('[data-start]').forEach(b=>b.addEventListener('click',()=>openStart(b.dataset.start,b.dataset.pack)));
  document.querySelectorAll('[data-credentials]').forEach(b=>b.addEventListener('click',()=>openCredentials(b.dataset.credentials)));
  document.querySelectorAll('[data-onboarding]').forEach(b=>b.addEventListener('click',()=>openOnboarding(b.dataset.onboarding)));
  document.querySelectorAll('[data-complete]').forEach(b=>b.addEventListener('click',()=>completeSubject(b.dataset.complete)));
  document.querySelectorAll('[data-gps-track]').forEach(b=>b.addEventListener('click',()=>openGpsTrack(b.dataset.gpsTrack)));
  document.querySelectorAll('[data-edit-subject]').forEach(b=>b.addEventListener('click',()=>openSubjectEdit(b.dataset.editSubject)));
}
async function renderSubjects(){subjectCache=await api('/api/v1/web/subjects');renderSubjectRows()}
function openSubjectEdit(pid){const x=subjectCache.find(row=>row.participant_id===pid);if(!x)return;selectedEditSubject=pid;$('subjectEditTitle').textContent=`编辑被试 ${pid}`;$('seBatch').value=x.batch_id||'';$('seRa').value=x.assigned_ra||'';$('seStart').value=x.start_date||x.expected_start||'';$('seEnd').value=x.end_date||x.expected_end||'';$('seNotes').value=x.notes||'';$('subjectEditDialog').showModal()}
async function saveSubjectEdit(){await api(`/api/v1/web/subjects/${encodeURIComponent(selectedEditSubject)}`,{method:'POST',body:JSON.stringify({batch_id:$('seBatch').value,assigned_ra:$('seRa').value,planned_start:$('seStart').value,planned_end:$('seEnd').value,notes:$('seNotes').value})});$('subjectEditDialog').close();toast('被试信息已更新');await renderSubjects()}
function formatGap(seconds){if(seconds===null||seconds===undefined)return '—';return seconds>=60?`${(seconds/60).toFixed(1)} min`:`${Number(seconds).toFixed(0)} s`}
function ensureGpsMap(config){
  if(!gpsTrackMap){gpsTrackMap=L.map('gpsTrackMap',{preferCanvas:true});gpsTrackLayers=L.layerGroup().addTo(gpsTrackMap)}
  if(!gpsTrackTile)gpsTrackTile=L.tileLayer(config.tile_url,{attribution:config.attribution,maxZoom:19}).addTo(gpsTrackMap);
}
async function openGpsTrack(pid){selectedTrackSubject=pid;gpsTrackHours=12;$('gpsTrackTitle').textContent=`被试 ${pid} · GPS 轨迹`;if(!$('gpsTrackDialog').open)$('gpsTrackDialog').showModal();await loadGpsTrack(gpsTrackHours)}
async function loadGpsTrack(hours){
  if(!selectedTrackSubject)return;gpsTrackHours=Number(hours);document.querySelectorAll('[data-track-hours]').forEach(b=>b.classList.toggle('active',Number(b.dataset.trackHours)===gpsTrackHours));
  $('gpsTrackMessage').className='muted track-message';$('gpsTrackMessage').textContent='正在读取轨迹…';
  try{
    const data=await api(`/api/v1/web/subjects/${encodeURIComponent(selectedTrackSubject)}/gps-track?hours=${gpsTrackHours}`);
    $('trackLatest').textContent=fmtTime(data.latest_recorded_at_utc);$('trackCount').textContent=String(data.total_point_count);$('trackGap').textContent=formatGap(data.max_gap_seconds);$('trackPoor').textContent=data.poor_accuracy_percentage===null?'—':`${data.poor_accuracy_percentage.toFixed(1)}%`;
    $('gpsTrackWindow').textContent=`最近 ${data.window_hours} h · 显示 ${data.points.length} / ${data.total_point_count} 点`;
    ensureGpsMap(data.map);gpsTrackLayers.clearLayers();
    if(!data.points.length){$('gpsTrackMessage').textContent='该时间窗内没有 GPS 位置记录';gpsTrackMap.setView([39.9,116.4],10);setTimeout(()=>gpsTrackMap.invalidateSize(),0);return}
    const segments=[];let segment=[];
    for(const point of data.points){if(point.break_before&&segment.length){segments.push(segment);segment=[]}segment.push([point.lat,point.lon])}if(segment.length)segments.push(segment);
    segments.filter(x=>x.length>1).forEach(x=>L.polyline(x,{color:'#2563a6',weight:4,opacity:.85}).addTo(gpsTrackLayers));
    const first=data.points[0],latest=data.points[data.points.length-1];
    L.circleMarker([first.lat,first.lon],{radius:6,color:'#fff',weight:2,fillColor:'#23834a',fillOpacity:1}).bindTooltip('起点').addTo(gpsTrackLayers);
    L.circleMarker([latest.lat,latest.lon],{radius:7,color:'#fff',weight:2,fillColor:'#c43d3d',fillOpacity:1}).bindTooltip('最新点').addTo(gpsTrackLayers);
    const bounds=L.latLngBounds(data.points.map(x=>[x.lat,x.lon]));bounds.isValid()&&data.points.length>1?gpsTrackMap.fitBounds(bounds,{padding:[24,24],maxZoom:17}):gpsTrackMap.setView([latest.lat,latest.lon],16);
    $('gpsTrackMessage').textContent=data.max_gap_seconds>data.gap_warning_seconds?`超过 ${data.gap_warning_seconds} s 的缺失时段已断开显示`:'轨迹连续时段已按时间连接';setTimeout(()=>gpsTrackMap.invalidateSize(),0);
  }catch(e){$('gpsTrackMessage').className='track-message error';$('gpsTrackMessage').textContent=e.message}
}
async function openCredentials(pid){selectedCredentialSubject=pid;const x=await api(`/api/v1/web/subjects/${pid}/credentials`);$('credentialTitle').textContent=`被试 ${pid} 凭据`;$('credGpsUrl').value=`${location.origin}/api/v1/gps/owntracks`;$('credGpsUser').value=pid;$('credGpsPassword').value=x.gps_password||'';$('credPortal').value=x.portal_path?location.origin+x.portal_path:'';$('credGpsHint').textContent=x.gps_exists&&!x.gps_password?'旧 GPS 密码无法恢复，请重置一次。':x.gps_password?'可随时复制；重置后旧密码立即失效。':'尚未生成。';$('credPortalHint').textContent=x.portal_exists&&!x.portal_path?'旧工作入口无法恢复，请重置一次。':x.portal_path?'可随时复制；重置后旧链接立即失效。':'尚未生成。';$('credGpsRotate').textContent=x.gps_exists?'重置 GPS 密码':'生成 GPS 密码';$('credPortalRotate').textContent=x.portal_exists?'重置工作入口':'生成工作入口';if(!$('credentialDialog').open)$('credentialDialog').showModal()}
async function rotateGps(){if(!confirm(`为 ${selectedCredentialSubject} 重新生成 GPS 密码？已有密码会立即失效。`))return;try{await api(`/api/v1/web/subjects/${selectedCredentialSubject}/gps-credential`,{method:'POST',body:'{}'});showOnboarding(await api(`/api/v1/web/subjects/${selectedCredentialSubject}/onboarding`));toast('GPS 密码已生成')}catch(e){$('credGpsHint').textContent=`生成失败：${e.message}`;toast(`GPS 密码生成失败：${e.message}`,'error')}}
async function rotatePortal(){if(!confirm(`为 ${selectedCredentialSubject} 重新生成被试入口？已有链接会立即失效。`))return;try{await api(`/api/v1/web/subjects/${selectedCredentialSubject}/portal`,{method:'POST',body:'{}'});showOnboarding(await api(`/api/v1/web/subjects/${selectedCredentialSubject}/onboarding`));await renderSubjects();toast('被试入口已生成')}catch(e){$('credPortalHint').textContent=`生成失败：${e.message}`;toast(`被试入口生成失败：${e.message}`,'error')}}
async function copyCredential(id){const value=$(id).value;if(!value){toast('请先生成或重置该凭据');return}try{await navigator.clipboard.writeText(value);toast('已复制')}catch{window.prompt('请复制：',value)}}
function openStart(pid){selectedSubject=pid;const subject=subjectCache.find(x=>x.participant_id===pid)||{},t=me.date_local;$('startDeviceFacts').innerHTML=`<strong>当前设备包 ${esc(subject.pack_id||'—')}</strong><span>Lighting ${esc(subject.light_serial||'—')} · AX3 ${esc(subject.ax3_serial||'—')}</span><span>正式开始时不会静默更换设备；如设备不对，请先使用“更换设备”。</span>`;$('sStart').value=t;$('sEnd').value=subject.expected_end||addLocalDays(t,13);$('startDialog').showModal()}
async function startSubject(){const x=await api(`/api/v1/web/subjects/${selectedSubject}/start`,{method:'POST',body:JSON.stringify({start_date:$('sStart').value,end_date:$('sEnd').value})});$('startDialog').close();toast('已启动运行');await renderSubjects();showOnboarding(x)}
async function completeSubject(pid){if(!confirm(`确认被试 ${pid} 已完成实验且设备已回收？完成后 GPS 将停止接收，Portal 仅供查看。`))return;await api(`/api/v1/web/subjects/${pid}/complete`,{method:'POST',body:'{}'});toast('实验已完成，设备已释放');await renderSubjects()}

function showOnboarding(x){onboardingData=x;selectedCredentialSubject=x.participant_id;$('onboardingTitle').textContent=`被试 ${x.participant_id} · 配置卡`;$('credGpsUrl').value=x.gps_url||`${location.origin}/api/v1/gps/owntracks`;$('credGpsUser').value=x.participant_id;$('credGpsPassword').value=x.gps_password||'';$('credPortal').value=x.portal_url||'';$('credGpsHint').textContent=x.gps_password?'可复制；重新生成后旧密码立即失效。':'尚未生成或旧密码无法恢复。';$('credPortalHint').textContent=x.portal_url?'可复制；重新生成后旧入口立即失效。':'尚未生成或旧入口无法恢复。';$('credGpsRotate').textContent=x.gps_password?'重新生成 GPS 密码':'生成 GPS 密码';$('credPortalRotate').textContent=x.portal_url?'重新生成被试入口':'生成被试入口';$('onboardingText').value=x.contact_text;const ready=Boolean(x.gps_password);$('owntracksIosDownload').href=ready?`/api/v1/web/subjects/${encodeURIComponent(x.participant_id)}/owntracks/ios`:'#';$('owntracksAndroidDownload').href=ready?`/api/v1/web/subjects/${encodeURIComponent(x.participant_id)}/owntracks/android`:'#';$('owntracksIosDownload').setAttribute('aria-disabled',String(!ready));$('owntracksAndroidDownload').setAttribute('aria-disabled',String(!ready));if(!$('onboardingDialog').open)$('onboardingDialog').showModal()}
async function openOnboarding(pid){showOnboarding(await api(`/api/v1/web/subjects/${pid}/onboarding`))}
async function copyText(value,message='已复制'){try{await navigator.clipboard.writeText(value);toast(message)}catch{window.prompt('请复制：',value)}}
function downloadOtrc(){if(!onboardingData)return;const blob=new Blob([onboardingData.owntracks_config_json],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`LEHUE-${onboardingData.participant_id}.otrc`;a.click();URL.revokeObjectURL(a.href)}
function reminderText(){const x=onboardingData;return `LEHUE 提醒｜被试 ${x.participant_id}\n我们注意到近期有一项采集需要确认。请打开被试入口查看 GPS、问卷或 Lighting 提示；如已处理可忽略。\n入口：${x.portal_url}`}
function endingText(){const x=onboardingData;return `LEHUE 实验结束提醒｜被试 ${x.participant_id}\n本轮实验计划于 ${x.end_date} 结束。请确认最后一次晨间问卷已提交，并按约定归还设备包 ${x.pack_id||''}。\n入口：${x.portal_url}`}

function yesNo(value){return value?badge('ok'):badge('missing')}
async function renderDailyQc(){const q=await api('/api/v1/web/daily-qc');const labels=[['暴露日','total'],['完整','ok'],['异常','missing'],['今日待完成','pending']];$('qcMetrics').innerHTML=labels.map(([label,key])=>`<div class="metric"><div class="label">${label}</div><div class="value">${q.summary[key]||0}</div></div>`).join('');$('qcRows').innerHTML=q.rows.slice().reverse().map(x=>`<tr><td>${esc(x.date_local)}</td><td><strong>${esc(x.participant_id)}</strong></td><td>${x.study_day}</td><td>${badge(x.status)}</td><td>${yesNo(x.evening)}</td><td>${badge(x.lighting)}${x.light_valid_pct!==null?` ${x.light_valid_pct}%`:''}</td><td>${badge(x.gps_quality)}${x.gps_point_count?` ${x.gps_point_count}点`:''}</td><td>${yesNo(x.morning)}</td><td>${esc(x.missing_items||'—')} ${x.status==='missing'?`<button class="btn small" data-qc-contact="${esc(x.participant_id)}" data-date="${esc(x.date_local)}" data-issues="${esc(x.missing_items)}" data-portal="${esc(x.portal_url||'')}">复制联系文本</button>`:''}</td></tr>`).join('');document.querySelectorAll('[data-qc-contact]').forEach(b=>b.addEventListener('click',()=>copyText(`LEHUE 采集提醒｜被试 ${b.dataset.qcContact}\n${b.dataset.date} 实验日需要确认：${b.dataset.issues}。请打开被试入口补充或检查；如已处理可忽略。${b.dataset.portal?`\n入口：${b.dataset.portal}`:''}`)));const light=await api('/api/v1/web/lighting');$('lightingRows').innerHTML=light.map(x=>`<tr><td>${esc(x.date_local)}</td><td><strong>${esc(x.participant_id)}</strong></td><td>${esc(x.original_filename)}</td><td>${badge(x.quality)}</td><td>${x.records_valid}/${x.records_total}</td><td>${x.valid_pct}%</td><td>${fmtTime(x.uploaded_at_utc)}</td><td>${esc(x.parse_error||'—')}</td></tr>`).join('')}
async function runDailyQc(){$('runQcBtn').disabled=true;try{const q=await api('/api/v1/web/daily-qc/run',{method:'POST',body:'{}'});toast(`核查完成：完整 ${q.summary.ok}，异常 ${q.summary.missing}，待完成 ${q.summary.pending}`);await renderDailyQc()}finally{$('runQcBtn').disabled=false}}

async function renderDevices(){const a=await api('/api/v1/web/devices');$('deviceRows').innerHTML=a.map(x=>`<tr><td><strong>${esc(x.pack_id)}</strong></td><td>${badge(x.status)}</td><td>${esc(x.current_participant_id||'—')}</td><td>${esc(x.light_serial||'—')}</td><td>${esc(x.ax3_serial||'—')}</td><td>${esc(x.issued_date||'—')}</td><td>${esc(x.expected_return_date||'—')}</td><td>${esc(x.notes||'')}</td></tr>`).join('')}
async function saveDevice(){await api('/api/v1/web/devices',{method:'POST',body:JSON.stringify({pack_id:$('dPack').value,status:$('dStatus').value,light_serial:$('dLight').value,ax3_serial:$('dAx3').value,notes:$('dNotes').value})});toast('设备包已保存');await renderDevices()}
function incidentBadge(status){return status==='closed'?'<span class="badge">已归档</span>':'<span class="badge danger">未归档</span>'}
async function renderIncidents(){incidentGroups=await api('/api/v1/web/incidents');$('incidentList').innerHTML=incidentGroups.length?incidentGroups.map((x,index)=>{const visible=x.status==='open'?x.issues.filter(issue=>issue.status!=='closed'):x.issues;return `<div class="incident-row ${x.status==='closed'?'archived':''}"><div class="incident-main"><div><strong>${esc(x.participant_id||'—')} · ${esc(x.date_local||'未指定日期')}</strong> ${incidentBadge(x.status)} <span class="badge">${visible.length} 项</span></div><div class="incident-issues">${visible.map(issue=>`<span>${esc(issue.summary||issue.incident_type||issue.source)}</span>`).join('')}</div></div><div class="row">${x.status==='open'?`<button class="btn small" data-incident-contact="${index}">复制联系文本</button>`:''}<button class="btn small" data-igroup="${index}" data-v="${x.status==='closed'?'open':'closed'}">${x.status==='closed'?'取消归档':'全部归档'}</button></div></div>`}).join(''):'<div class="muted">暂无异常记录</div>';document.querySelectorAll('[data-igroup]').forEach(b=>b.addEventListener('click',()=>setIncidentGroupStatus(Number(b.dataset.igroup),b.dataset.v)));document.querySelectorAll('[data-incident-contact]').forEach(b=>b.addEventListener('click',()=>copyText(incidentGroups[Number(b.dataset.incidentContact)].contact_text)))}
async function addIncident(){const summary=$('iSummary').value.trim();if(!summary){toast('请填写异常描述');return}await api('/api/v1/web/incidents',{method:'POST',body:JSON.stringify({participant_id:$('iPid').value,date_local:$('iDate').value,source:$('iSource').value,summary})});$('iSummary').value='';toast('异常已记录');await renderIncidents()}
async function setIncidentStatus(uid,v){await api(`/api/v1/web/incidents/${uid}/status`,{method:'POST',body:JSON.stringify({status:v})});await renderIncidents()}
async function setIncidentGroupStatus(index,status){const group=incidentGroups[index],targets=group.issues.filter(issue=>issue.status!==status);await Promise.all(targets.map(issue=>api(`/api/v1/web/incidents/${encodeURIComponent(issue.incident_uid)}/status`,{method:'POST',body:JSON.stringify({status})})));await renderIncidents()}

async function renderUsers(){const a=await api('/api/v1/web/users');$('userRows').innerHTML=a.map(x=>`<tr><td><strong>${esc(x.username)}</strong></td><td>${esc(x.display_name||'—')}</td><td>${badge(x.role)}</td><td>${badge(x.is_active?'active':'inactive')}</td><td>${fmtTime(x.created_at_utc)}</td><td><div class="user-actions"><button class="btn small" data-reset="${esc(x.username)}">重置密码</button>${x.username!==me.username?`<button class="btn small ${x.is_active?'danger':''}" data-active="${esc(x.username)}" data-value="${x.is_active?'0':'1'}">${x.is_active?'禁用':'启用'}</button>`:''}</div></td></tr>`).join('');document.querySelectorAll('[data-reset]').forEach(b=>b.addEventListener('click',()=>resetUser(b.dataset.reset)));document.querySelectorAll('[data-active]').forEach(b=>b.addEventListener('click',()=>setUserActive(b.dataset.active,b.dataset.value==='1')))}
async function addUser(){const body={username:$('uUsername').value,display_name:$('uDisplay').value,role:$('uRole').value,password:$('uPassword').value};const x=await api('/api/v1/web/users',{method:'POST',body:JSON.stringify(body)});alert(`账号已创建\n用户名: ${x.username}\n密码: ${x.password}\n\n请立即交给对应协作者。`);$('uPassword').value='';await renderUsers()}
async function setUserActive(username,isActive){if(!confirm(`${isActive?'启用':'禁用'}账号 ${username}？`))return;await api(`/api/v1/web/users/${encodeURIComponent(username)}/active`,{method:'POST',body:JSON.stringify({is_active:isActive})});await renderUsers()}
async function resetUser(username){const p=prompt(`重置 ${username} 的密码。可留空自动生成强密码：`,'');if(p===null)return;const x=await api(`/api/v1/web/users/${encodeURIComponent(username)}/reset-password`,{method:'POST',body:JSON.stringify({password:p})});alert(`密码已重置\n用户名: ${x.username}\n新密码: ${x.password}\n\n该账号现有登录会话已失效。`)}
const baseBadge=badge;
badge=function(v){const flow={ready:['Ready','ok'],outbound:['配送中','info'],in_use:['使用中','warn'],returning:['待回收','warn'],returned:['已回收','info']};const x=flow[v];return x?`<span class="badge ${x[1]}">${x[0]}</span>`:baseBadge(v)};
async function openPrepare(pid){selectedSubject=pid;const packs=(await api('/api/v1/web/devices')).filter(x=>x.status==='available'&&!x.current_participant_id);$('prepPack').innerHTML=packs.map(x=>`<option value="${esc(x.pack_id)}">${esc(x.pack_id)} · Lighting ${esc(x.light_serial||'—')} · AX3 ${esc(x.ax3_serial||'—')}</option>`).join('');$('prepareSubmit').disabled=!packs.length;$('prepDelivery').value='';$('prepTracking').value='';$('prepareDialog').showModal()}
async function prepareSubject(){const x=await api(`/api/v1/web/subjects/${selectedSubject}/prepare`,{method:'POST',body:JSON.stringify({pack_id:$('prepPack').value,delivery_method:$('prepDelivery').value,tracking_number:$('prepTracking').value})});$('prepareDialog').close();toast('已进入准备测试；Ready 将由 GPS 和 Lighting 回传自动判断');await renderSubjects();showOnboarding(x)}
async function promote(){const body={participant_id:$('pId').value,batch_id:$('pBatch').value,expected_start:$('pStart').value,expected_end:$('pEnd').value,assigned_ra:$('pRa').value};await api(`/api/v1/web/candidates/${selectedCandidate}/promote`,{method:'POST',body:JSON.stringify(body)});$('promoteDialog').close();toast('已创建预约');await renderCandidates()}
async function completeSubject(pid){const subject=subjectCache.find(x=>x.participant_id===pid);if(subject?.awaiting_final_morning){const force=!confirm('确认最终晨间和 S2 已完成并正式结题？\n选择“取消”可进入人工强制结题。');let reason='';if(force){reason=prompt('请输入强制结题原因：','')||'';if(!reason)return}await api(`/api/v1/web/subjects/${pid}/complete`,{method:'POST',body:JSON.stringify({force,reason})});toast('结题完成');await renderSubjects();return}const finalEnd=prompt('请输入真实最后 exposure day：',me.date_local);if(!finalEnd)return;await api(`/api/v1/web/subjects/${pid}/end-exposure`,{method:'POST',body:JSON.stringify({final_end:finalEnd})});toast('正式曝光已结束；等待最终晨间、S2 和必要补传');await renderSubjects()}
async function terminateSubject(pid){const reason=prompt('请输入提前退出原因：','');if(!reason)return;const finalEnd=prompt('请输入实际最后 exposure day：',me.date_local);if(!finalEnd)return;await api(`/api/v1/web/subjects/${pid}/terminate`,{method:'POST',body:JSON.stringify({final_end:finalEnd,reason})});toast('已停止后续正式曝光并保留已有数据');await renderSubjects()}
function openCancelPreparation(pid){selectedSubject=pid;$('cancelPrepReason').value='';$('cancelPrepSent').checked=false;$('cancelPreparationDialog').showModal()}
async function cancelPreparation(){await api(`/api/v1/web/subjects/${selectedSubject}/cancel-preparation`,{method:'POST',body:JSON.stringify({reason:$('cancelPrepReason').value,device_sent:$('cancelPrepSent').checked})});$('cancelPreparationDialog').close();toast('准备已取消，凭据已撤销');await renderSubjects()}
async function deviceFlow(pack,action){await api(`/api/v1/web/devices/${encodeURIComponent(pack)}/flow`,{method:'POST',body:JSON.stringify({action})});toast(action==='confirm-returned'?'已确认实际收回':'已整备并恢复可用');await renderDevices()}
function downloadBackup(){location.href='/api/v1/web/backup'}
async function openReplaceDevice(pid){selectedSubject=pid;const [packs,history]=await Promise.all([api('/api/v1/web/devices'),api(`/api/v1/web/device-assignments?participant_id=${encodeURIComponent(pid)}`)]);const available=packs.filter(x=>x.status==='available'&&!x.current_participant_id);$('replaceDeviceTitle').textContent=`被试 ${pid} · 运行中更换设备`;$('replacePack').innerHTML=available.map(x=>`<option value="${esc(x.pack_id)}">${esc(x.pack_id)} · Lighting ${esc(x.light_serial||'—')} · AX3 ${esc(x.ax3_serial||'—')}</option>`).join('');$('replaceDate').value=me.date_local;$('replaceReason').value='';$('assignmentHistory').innerHTML='<strong>分配历史</strong><br>'+history.map(x=>`${esc(x.effective_from_date)}${x.effective_to_date?` → ${esc(x.effective_to_date)}`:' → 当前'} · ${esc(x.pack_id)}${x.reason?` · ${esc(x.reason)}`:''}`).join('<br>');$('replaceDeviceSubmit').disabled=!available.length;$('replaceDeviceDialog').showModal()}
async function replaceDevice(){await api(`/api/v1/web/subjects/${encodeURIComponent(selectedSubject)}/replace-device`,{method:'POST',body:JSON.stringify({pack_id:$('replacePack').value,effective_date:$('replaceDate').value,reason:$('replaceReason').value})});$('replaceDeviceDialog').close();toast('设备已更换，原分配历史已保留');await renderSubjects()}
let selectedEndSubject=null;
function subjectDeviceText(subject){return subject.pack_id?`当前设备包 ${esc(subject.pack_id)} · Lighting ${esc(subject.light_serial||'—')} · AX3 ${esc(subject.ax3_serial||'—')}`:'当前未分配设备包'}
function studyProgress(subject){if(subject.status!=='running'||!subject.start_date||!subject.end_date)return '—';const start=new Date(`${subject.start_date}T00:00:00Z`),end=new Date(`${subject.end_date}T00:00:00Z`),today=new Date(`${me.date_local}T00:00:00Z`),dayMs=86400000,total=Math.max(1,Math.round((end-start)/dayMs)+1),elapsed=Math.max(0,Math.min(total,Math.floor((today-start)/dayMs)+1)),day=subject.study_day||elapsed,pct=Math.max(0,Math.min(100,Math.round(elapsed/total*100)));return `<div class="study-progress"><div class="study-progress-label"><strong>Day ${esc(day)}</strong><span>${elapsed} / ${total} 天</span></div><div class="study-progress-track" role="progressbar" aria-label="实验运行进度" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${elapsed}"><span style="width:${pct}%"></span></div></div>`}
openSubjectEdit=function(pid){const x=subjectCache.find(row=>row.participant_id===pid);if(!x)return;selectedEditSubject=pid;$('subjectEditTitle').textContent=`编辑被试 ${pid}`;$('seBatch').value=x.batch_id||'';$('seRa').value=x.assigned_ra||'';$('seStart').value=x.start_date||x.expected_start||'';$('seEnd').value=x.end_date||x.expected_end||'';$('seNotes').value=x.notes||'';const startLocked=x.status==='running'||x.status==='completed';$('seStart').disabled=startLocked;$('subjectEditDateHint').textContent=startLocked?'正式运行后开始日期已锁定；如需修正请走专项数据修正。结束日期仍可按实际情况调整。':'日期可随实验实际情况调整；正式运行后开始日期将锁定。';$('subjectEditDevice').innerHTML=`<strong>设备归属</strong><span>${subjectDeviceText(x)}</span>`;const canReplace=Boolean(x.preparation_started_at_utc)&&(['scheduled','ready'].includes(x.status)||(x.status==='running'&&!x.awaiting_final_morning));$('editReplaceDeviceBtn').classList.toggle('hidden',!canReplace);$('editCancelPreparationBtn').classList.toggle('hidden',!(x.preparation_started_at_utc&&['scheduled','ready'].includes(x.status)));$('subjectEditDialog').showModal()};
function updateEndStudyForm(){const subject=subjectCache.find(x=>x.participant_id===selectedEndSubject);if(!subject)return;const type=$('endStudyType').value,awaiting=Boolean(subject.awaiting_final_morning),needsReason=type==='early'||type==='force';$('endStudyDateField').classList.toggle('hidden',awaiting);$('endStudyReasonField').classList.toggle('hidden',!needsReason);$('endStudyHint').textContent=awaiting?(type==='force'?'仅在最终晨间/S2 无法正常完成时使用，并保留原因。':'确认最终晨间、S2 和必要补传已完成后正式结题。'):(type==='early'?'停止后续正式任务，保留已有数据，设备进入待回收。':'固定最后 exposure day，转入 Day15 最终晨间/S2 和必要补传阶段。')}
function openEndStudy(pid){const subject=subjectCache.find(x=>x.participant_id===pid);if(!subject)return;selectedEndSubject=pid;$('endStudyTitle').textContent=subject.awaiting_final_morning?`完成结题 · ${pid}`:`实验结束 · ${pid}`;$('endStudySummary').innerHTML=`<strong>${esc(subject.name||pid)}</strong><span>${subjectDeviceText(subject)}</span>`;$('endStudyReason').value='';if(subject.awaiting_final_morning){$('endStudyType').replaceChildren(new Option('完成结题','closeout'),new Option('强制结题','force'))}else{$('endStudyType').replaceChildren(new Option('按计划结束正式曝光','normal'),new Option('提前终止（被试退出等）','early'));$('endStudyDate').value=me.date_local}$('endStudySubmit').textContent=subject.awaiting_final_morning?'确认结题':'确认结束';updateEndStudyForm();$('endStudyDialog').showModal()}
async function submitEndStudy(){const subject=subjectCache.find(x=>x.participant_id===selectedEndSubject);if(!subject)return;const type=$('endStudyType').value,reason=$('endStudyReason').value.trim();if((type==='early'||type==='force')&&!reason){toast('请填写原因','error');$('endStudyReason').focus();return}if(subject.awaiting_final_morning){await api(`/api/v1/web/subjects/${encodeURIComponent(selectedEndSubject)}/complete`,{method:'POST',body:JSON.stringify({force:type==='force',reason})});toast(type==='force'?'已强制结题并记录原因':'结题完成')}else{const finalEnd=$('endStudyDate').value;if(!finalEnd){toast('请选择实际最后 exposure day','error');return}const endpoint=type==='early'?'terminate':'end-exposure';await api(`/api/v1/web/subjects/${encodeURIComponent(selectedEndSubject)}/${endpoint}`,{method:'POST',body:JSON.stringify({final_end:finalEnd,reason})});toast(type==='early'?'已提前终止；已有数据保留':'正式曝光已结束，等待最终晨间与 S2')}$('endStudyDialog').close();await renderSubjects()}
renderSubjectRows=function(){const q=$('subjectSearch').value.trim().toLowerCase(),filter=$('subjectStatus').value;const rows=subjectCache.filter(x=>{const text=`${x.participant_id} ${x.name||''}`.toLowerCase();return(!q||text.includes(q))&&(filter==='all'||filter===x.status)});$('subjectCount').textContent=`显示 ${rows.length} / 共 ${subjectCache.length}`;$('subjectRows').innerHTML=rows.map(x=>{const lifecycle=x.status==='scheduled'&&!x.preparation_started_at_utc?`<button class="btn small primary" data-prepare="${esc(x.participant_id)}">准备测试</button>`:x.status==='ready'?`<button class="btn small primary" data-start="${esc(x.participant_id)}" data-pack="${esc(x.pack_id||'')}">正式开始</button>`:x.status==='running'?`<button class="btn small ${x.awaiting_final_morning?'primary':'danger'}" data-end-study="${esc(x.participant_id)}">${x.awaiting_final_morning?'完成结题':'实验结束'}</button>`:'';const lighting=x.status==='running'?(x.lighting_current?.uploaded?`${badge(x.lighting_current.quality)} ${x.lighting_current.valid_pct??''}%<br><span class="muted">${esc(x.lighting_target_date||'')}</span>`:`未上传<br><span class="muted">${esc(x.lighting_target_date||'')}</span>`):(x.lighting_test_uploaded?'测试 ✓':(x.preparation_started_at_utc?'测试待上传':'—'));const showConfiguration=x.status==='running'||(x.preparation_started_at_utc&&x.status!=='completed');return `<tr data-participant-id="${esc(x.participant_id)}"><td><strong>${esc(x.participant_id)}</strong></td><td>${esc(x.name||'—')}<br><span class="muted">${esc(x.phone||'')}</span></td><td>${badge(x.status)}${x.awaiting_final_morning?'<br><span class="muted">等待最终晨间 / S2</span>':(x.preparation_started_at_utc&&x.status==='scheduled'?'<br><span class="muted">准备测试中</span>':'')}</td><td>${x.status==='running'&&x.study_day?`Day ${x.study_day}`:'—'}</td><td>${esc(x.start_date||x.expected_start||'—')} → ${esc(x.end_date||x.expected_end||'—')}</td><td>${esc(x.pack_id||'—')} ${x.logistics_status?badge(x.logistics_status):''}</td><td>${esc(x.assigned_ra||'—')}</td><td><div class="gps-cell">${gpsBadge(x.gps_status)}<span class="muted">${x.gps_last_received_at_utc?fmtTime(x.gps_last_received_at_utc):(x.gps_test_received?'测试已收到':'暂无回传')}</span></div></td><td>${x.questionnaire_today_completed||0}/2</td><td>${lighting}</td><td>${x.portal_enabled?badge('connected'):'未生成'}</td><td><div class="subject-actions">${lifecycle}<button class="btn small" data-edit-subject="${esc(x.participant_id)}">编辑</button>${showConfiguration?`<button class="btn small" data-onboarding="${esc(x.participant_id)}">配置卡</button>`:''}<button class="btn small" data-gps-track="${esc(x.participant_id)}">轨迹</button></div></td></tr>`}).join('');document.querySelectorAll('[data-prepare]').forEach(b=>b.addEventListener('click',()=>openPrepare(b.dataset.prepare)));document.querySelectorAll('[data-start]').forEach(b=>b.addEventListener('click',()=>openStart(b.dataset.start,b.dataset.pack)));document.querySelectorAll('[data-end-study]').forEach(b=>b.addEventListener('click',()=>openEndStudy(b.dataset.endStudy)));document.querySelectorAll('[data-edit-subject]').forEach(b=>b.addEventListener('click',()=>openSubjectEdit(b.dataset.editSubject)));document.querySelectorAll('[data-onboarding]').forEach(b=>b.addEventListener('click',()=>openOnboarding(b.dataset.onboarding)));document.querySelectorAll('[data-gps-track]').forEach(b=>b.addEventListener('click',()=>openGpsTrack(b.dataset.gpsTrack)))};
