async function restoreStateBundle(){const file=$('stateBundleFile').files[0];if(!file){toast('请选择 State Bundle ZIP');return}if(!confirm('将用所选 State Bundle 整包替换当前状态。系统会先自动保存 rollback，是否继续？'))return;const button=$('restoreStateBundleBtn');button.disabled=true;try{const result=await api('/api/v1/web/state-bundle/restore',{method:'POST',headers:{'Content-Type':'application/zip'},body:file});alert(`状态恢复完成。\n凭据已按本服务器密钥重新加密。\nRollback: ${result.rollback_state_bundle}\n\n登录会话不会迁移，请重新登录。`);location.reload()}finally{button.disabled=false}}

